sources.matchedDeclaration:
create index if not exists auth_provisioning_events_email_created_idx
  on public.auth_provisioning_events(lower(email), created_at desc)
  where email is not null;

create index if not exists authorization_scopes_company_customer_active_idx
      on public.authorization_scopes(company_id, customer_id, created_at desc)
      where status = 'active' and revoked_at is null;

create index if not exists billing_disputes_customer_number_idx
  on public.billing_disputes(company_id, customer_number, received_at desc)
  where customer_number is not null;

create index if not exists billing_export_run_items_company_blocker_case_v1b_idx
      on public.billing_export_run_items(company_id, blocker_case_id)
      where blocker_case_id is not null;

create index if not exists billing_export_run_items_company_run_status_v1b_idx
      on public.billing_export_run_items(company_id, billing_export_run_id, status)
      where billing_export_run_id is not null;

create index if not exists billing_partner_customers_customer_number_idx
  on public.billing_partner_customers(company_id, customer_number)
  where customer_number is not null;

create index if not exists billing_partner_customers_provider_debtor_idx
  on public.billing_partner_customers(provider, provider_debtor_id)
  where provider_debtor_id is not null;

create index if not exists idx_communication_routes_customer_masterdata
  on public.communication_routes (company_id, route_scope, grid_owner_id, is_active)
  where route_scope = 'customer_masterdata';

CREATE INDEX IF NOT EXISTS companies_org_number_idx
  ON public.companies (org_number)
  WHERE org_number IS NOT NULL;

create unique index if not exists company_invitations_accept_token_hash_uidx
  on public.company_invitations(accept_token_hash)
  where accept_token_hash is not null;

CREATE INDEX IF NOT EXISTS company_invitations_email_pending_idx
  ON public.company_invitations (lower(email), status)
  WHERE status = 'pending';

create index if not exists customer_blockers_company_customer_open_idx
      on public.customer_blockers(company_id, customer_id, blocker_type, created_at desc)
      where status in ('open', 'pending_review');

create index if not exists customer_lifecycle_decisions_active_switch_idx
      on public.customer_lifecycle_decisions(company_id, customer_id, decision_type, scope_type, scope_id, created_at desc)
      where coalesce(status, 'active') = 'active';

create index if not exists idx_customer_operation_tasks_batch7a_source
  on public.customer_operation_tasks(company_id, task_type, status)
  where status = 'open';

create index if not exists customer_portal_identities_api_client_idx
  on public.customer_portal_identities(api_client_id, created_at desc)
  where api_client_id is not null;

create index if not exists customers_company_identity_idx
      on public.customers(company_id, personal_number, org_number)
      where company_id is not null;

create index if not exists customers_company_status_created_perf_idx
      on public.customers(company_id, status, created_at desc)
      where company_id is not null;

create index if not exists customers_company_type_status_created_perf_idx
      on public.customers(company_id, customer_type, status, created_at desc)
      where company_id is not null;

create index if not exists data_quality_findings_customer_idx
  on public.data_quality_findings(company_id, customer_id, status, detected_at desc)
  where customer_id is not null;

create index if not exists document_ai_extractions_import_batch_idx
      on public.document_ai_extractions(company_id, import_batch_id, created_at desc)
      where import_batch_id is not null;

create index if not exists ediel_actor_settings_brp_ediel_id_idx
      on public.ediel_actor_settings(brp_ediel_id)
      where brp_ediel_id is not null;

create index if not exists ediel_message_rules_runtime_v1b_idx
      on public.ediel_message_rules(message_family, message_code, message_standard, direction, is_active, valid_from desc, valid_to)
      where is_active = true;

create unique index if not exists ediel_outbound_queue_company_idempotency_uidx
  on public.ediel_outbound_queue(company_id, idempotency_key)
  where idempotency_key is not null;

create index if not exists ediel_route_profiles_environment_type_idx
  on public.ediel_route_profiles(company_id, environment_type, message_family, business_code)
  where coalesce(is_active, true) = true and coalesce(is_enabled, true) = true;

create unique index if not exists ediel_test_run_locks_one_active_agt_uidx
  on public.ediel_test_run_locks(company_id, actor_role, message_family, environment_type)
  where released_at is null;

create index if not exists ediel_unlinked_test_messages_open_idx
  on public.ediel_unlinked_test_messages(environment_type, message_family, status)
  where status = 'unlinked';

create unique index if not exists idx_inbound_email_company_interchange_uidx
  on public.inbound_email_messages(environment, company_id, sender_ediel_id, interchange_reference)
  where company_id is not null and sender_ediel_id is not null and interchange_reference is not null;

create unique index if not exists idx_inbound_email_company_transaction_external_uidx
  on public.inbound_email_messages(environment, company_id, sender_ediel_id, transaction_reference, external_reference)
  where company_id is not null and sender_ediel_id is not null and transaction_reference is not null and external_reference is not null;

create unique index if not exists idx_inbound_email_mailbox_message_id_uidx
  on public.inbound_email_messages(mailbox_id, internet_message_id)
  where internet_message_id is not null;

create unique index if not exists idx_inbound_email_mailbox_raw_hash_uidx
  on public.inbound_email_messages(mailbox_id, raw_message_sha256)
  where raw_message_sha256 is not null;

create unique index if not exists ux_inbound_processing_jobs_one_open_per_email
  on public.inbound_processing_jobs(inbound_email_message_id)
  where inbound_email_message_id is not null and status in ('queued', 'retry', 'processing');

create index if not exists invoice_export_items_customer_number_idx
      on public.invoice_export_items(company_id, customer_number, created_at desc)
      where customer_number is not null;

create index if not exists invoice_export_items_dispute_status_idx
      on public.invoice_export_items(company_id, dispute_status, created_at desc)
      where dispute_status is not null;

create index if not exists invoice_export_items_provider_customer_idx
      on public.invoice_export_items(provider, provider_customer_id)
      where provider_customer_id is not null;

create index if not exists idx_metering_values_batch7a_canonical
  on public.metering_values(company_id, canonical_dedupe_key)
  where canonical_dedupe_key is not null;

create unique index if not exists metering_values_current_dedupe_uidx
      on public.metering_values(company_id, canonical_dedupe_key)
      where is_current = true and canonical_dedupe_key is not null;

create index if not exists idx_outbound_requests_batch7a_overdue
  on public.outbound_requests(company_id, status, message_code, sent_at, acknowledged_at)
  where status in ('queued', 'prepared', 'sent', 'syntax_accepted', 'application_accepted', 'acknowledged');

create index if not exists idx_outbound_requests_customer_masterdata
  on public.outbound_requests (company_id, source_type, source_id, status)
  where request_type = 'customer_masterdata';

create index if not exists partner_exports_batch_key_idx
      on public.partner_exports(company_id, export_batch_key)
      where export_batch_key is not null;

create unique index if not exists permissions_key_unique_idx
      on public.permissions (key)
      where key is not null;

create index if not exists powers_of_attorney_company_customer_signed_idx
      on public.powers_of_attorney(company_id, customer_id, signed_at desc)
      where status = 'signed';

create unique index if not exists roles_key_unique_idx
      on public.roles (key)
      where key is not null;

create index if not exists supplier_switch_requests_lifecycle_block_idx
      on public.supplier_switch_requests(company_id, customer_id, lifecycle_blocked, status, created_at desc)
      where lifecycle_blocked = true;

create index if not exists supplier_switch_requests_open_company_customer_idx
      on public.supplier_switch_requests(company_id, customer_id, site_id, status, created_at desc)
      where status in ('draft','queued','submitted','accepted','cancellation_requested','cancellation_sent','manual_followup_required');

create unique index if not exists tenant_email_sender_profiles_default_idx
  on public.tenant_email_sender_profiles(company_id)
  where is_default = true and status = 'verified';

create index if not exists user_roles_company_user_active_idx
      on public.user_roles(company_id, user_id, status, is_active)
      where company_id is not null and user_id is not null;

create index if not exists webhook_subscriptions_api_client_idx
  on public.webhook_subscriptions(api_client_id, status, created_at desc)
  where api_client_id is not null;
